def l = ctx.rule?.level;
if (l == null) { return; }
int lv;
if (l instanceof Integer) { lv = l; } else { lv = Integer.parseInt(l.toString()); }
String s;
int o;
if (lv >= 15) { s = 'Critical'; o = 5; }
else if (lv >= 11) { s = 'High'; o = 4; }
else if (lv >= 7) { s = 'Medium'; o = 3; }
else if (lv >= 5) { s = 'Low'; o = 2; }
else { s = 'Info'; o = 1; }
if (o > 1) {
  def ts = ctx.timestamp;
  if (ts != null) {
    try {
      def fmt = DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss.SSSZ").withZone(ZoneId.of('UTC'));
      def zdt = ZonedDateTime.parse(ts, fmt);
      def paris = zdt.withZoneSameInstant(ZoneId.of('Europe/Paris'));
      int hour = paris.getHour();
      if (hour >= 20 || hour < 7) {
        o = o + 1;
        if (o > 5) { o = 5; }
        if (o == 5) { s = 'Critical'; }
        else if (o == 4) { s = 'High'; }
        else if (o == 3) { s = 'Medium'; }
      }
    } catch (Exception e) { }
  }
}
ctx.rule.severity = s;
ctx.rule.severity_order = o;

def dn = ctx.decoder?.name;
def g = ctx.rule?.groups;
String d;
if (ctx.timestamp != null && ctx.timestamp.length() >= 10) {
  d = ctx.timestamp.substring(0,10).replace('-','.');
} else { return; }
if (dn == 'pf-nohost') { ctx._index = 'wazuh-firewall-' + d; return; }
if (dn == 'npm-access') { ctx._index = 'wazuh-proxy-' + d; return; }
if (dn == 'jellyfin') { ctx._index = 'wazuh-jellyfin-' + d; return; }
if (dn == 'wg-monitor') { ctx._index = 'wazuh-vpn-' + d; return; }
if (g != null && g.contains('dns')) { ctx._index = 'wazuh-dns-' + d; return; }
def aid = ctx.agent?.id;
if (aid == null || aid == '000') { return; }
def loc = ctx.location;
boolean web = g != null && (g.contains('web') || g.contains('apache') || g.contains('nginx') || g.contains('iis'));
boolean windows = (g != null && g.contains('windows')) || ctx.data?.win != null;
boolean linux = (g != null && (g.contains('syslog') || g.contains('sshd') || g.contains('pam') || g.contains('systemd') || g.contains('audit') || g.contains('adduser') || g.contains('authentication_success') || g.contains('authentication_failed'))) || (loc instanceof String && (loc.startsWith('/var/log') || loc == 'journald'));
if (web) { ctx._index = 'wazuh-web-' + d; }
else if (windows) { ctx._index = 'wazuh-windows-' + d; }
else if (linux) { ctx._index = 'wazuh-linux-' + d; }
